                    }
                    Spacer()
                    Picker("项目", selection: $model.project) { Text("全部项目").tag(""); ForEach(model.projects, id: \.self) { Text(URL(fileURLWithPath: $0).lastPathComponent).tag($0) } }.frame(width: 160)
